<template><q-page class="q-pa-lg"><div class="row items-center justify-between q-mb-lg"><div class="text-h4">Kategorije</div><q-btn color="primary" icon="add" label="Dodaj" @click="open()" /></div><div class="row q-col-gutter-md"><div v-for="item in items" :key="item.id_kategorija" class="col-12 col-sm-6 col-md-4"><q-card><q-card-section><div class="text-h6">{{ item.naziv }}</div><div class="text-caption">{{ item.opis || 'Bez opisa' }}</div></q-card-section><q-card-actions align="right"><q-btn flat icon="edit" @click="open(item)"/><q-btn flat color="negative" icon="delete" @click="remove(item)"/></q-card-actions></q-card></div></div><q-dialog v-model="dialog"><q-card style="min-width: 360px"><q-card-section class="text-h6">{{ form.id_kategorija ? 'Uredi' : 'Dodaj' }} kategoriju</q-card-section><q-card-section><q-input v-model="form.naziv" label="Naziv" outlined/><q-input v-model="form.opis" label="Opis" type="textarea" outlined class="q-mt-md"/></q-card-section><q-card-actions align="right"><q-btn flat label="Odustani" v-close-popup/><q-btn color="primary" label="Spremi" @click="save"/></q-card-actions></q-card></q-dialog></q-page></template>
<script setup>
import { onMounted, reactive, ref } from 'vue'; import { useQuasar } from 'quasar'; import { api } from 'boot/axios';
const $q=useQuasar(); const items=ref([]); const dialog=ref(false); const form=reactive({id_kategorija:null,naziv:'',opis:''});
async function load(){items.value=(await api.get('/kategorije')).data;} function open(x=null){Object.assign(form,{id_kategorija:x?.id_kategorija||null,naziv:x?.naziv||'',opis:x?.opis||''});dialog.value=true;} async function save(){try{if(form.id_kategorija) await api.put(`/kategorije/${form.id_kategorija}`,form);else await api.post('/kategorije',form);dialog.value=false;await load();}catch(e){$q.notify({type:'negative',message:e.response?.data?.message||'Greška pri spremanju.'});}} async function remove(x){if(!confirm(`Obrisati "${x.naziv}"?`))return;try{await api.delete(`/kategorije/${x.id_kategorija}`);await load();}catch(e){$q.notify({type:'negative',message:e.response?.data?.message||'Brisanje nije moguće.'});}} onMounted(load);
</script>
